import csv
series={
 'AHU01':'47f1370e-62d8-56c6-8ae6-d34fa69cf177',
 'AHU02':'03f8d175-8f4f-5a5c-8017-4cac0978dde8',
 'AHU03':'f0a0044c-9c90-58fc-b425-307d0c874a2a',
}
data={k:[] for k in series}
with open(VALUES_CSV) as f:
    for row in csv.DictReader(f):
        for k,v in series.items():
            if v==row['timeseries_id']:
                data[k].append((row['timestamp'],float(row['value'])))

for k in series:
    day=[v for t,v in data[k] if t.startswith('2018-07-24')]
    daymax=max(day)
    recmax=max(v for t,v in data[k])
    print(k,'daymax',daymax,'recmax',recmax,'ratio',daymax/recmax)
